  virtual void handleAuthenticate(ccxt::any client, ccxt::any message) {
    //
    //  { event: "login", code: 0 }
    //
    ccxt::any messageHash = std::string("authenticated");
    ccxt::any future = this->safeValue(
        ::getValue(client, std::string("futures")), messageHash);
    ::wsFutureResolve(future, true);
  }

  virtual ccxt::any handleErrorMessage(ccxt::any client, ccxt::any message) {
    //
    //    { event: "error", code: 30015, msg: "Invalid sign" }
    //
    ccxt::any event = this->safeString(message, std::string("event"));
    try {
      if (isTrue(isEqual(event, std::string("error")))) {
        ccxt::any code = this->safeString(message, std::string("code"));
        ccxt::any feedback =
            add(add(this->id, std::string(" ")), this->json(message));
        this->throwExactlyMatchedException(
            ::getValue(::getValue(this->exceptions, std::string("ws")),
                       std::string("exact")),
            code, feedback);
        ccxt::any msg =
            this->safeString(message, std::string("msg"), std::string(""));
        this->throwBroadlyMatchedException(
            ::getValue(::getValue(this->exceptions, std::string("ws")),
                       std::string("broad")),
            msg, feedback);
        throw ExchangeError(toString(feedback));
      }
      return false;
    } catch (const std::exception &e) {
      if (isTrue(isInstanceOf<AuthenticationError>(e))) {
        ccxt::any messageHash = std::string("authenticated");
        this->reject(e, messageHash);
        if (isTrue(inOp(::getValue(client, std::string("subscriptions")),
                        messageHash))) {
          deleteKey(::getValue(client, std::string("subscriptions")),
                    messageHash);
        }
      } else {
        // Note: if error happens on a subscribe event, user will have to close
        // exchange to resubscribe. Issue #19041
        this->reject(e);
      }
      return true;
    }
  }

  void handleMessage(ccxt::any client, ccxt::any message) override {
    //
    //   {
    //       "action": "snapshot",
    //       "arg": { instType: 'SPOT', channel: "ticker", instId: "BTCUSDT" },
    //       "data": [
    //         {
    //           "instId": "BTCUSDT",
    //           "last": "21150.53",
    //           "open24h": "20759.65",
    //           "high24h": "21202.29",
    //           "low24h": "20518.82",
    //           "bestBid": "21150.500000",
    //           "bestAsk": "21150.600000",
    //           "baseVolume": "25402.1961",
    //           "quoteVolume": "530452554.2156",
    //           "ts": 1656408934044,
    //           "labeId": 0
    //         }
    //       ]
    //   }
    // pong message
    //    "pong"
    //
    // login
    //
    //     { event: "login", code: 0 }
    //
    // subscribe
    //
    //    {
    //        "event": "subscribe",
    //        "arg": { instType: 'SPOT', channel: "account", instId: "default" }
    //    }
    // unsubscribe
    //    {
    //        "op":"unsubscribe",
    //        "args":[
    //          {
    //            "instType":"USDT-FUTURES",
    //            "channel":"ticker",
    //            "instId":"BTCUSDT"
    //          }
    //        ]
    //    }
    //
    // uta
    //
    //     {
    //         "action": "snapshot",
    //         "arg": { "instType": "spot", topic: "ticker", symbol: "BTCUSDT"
    //         }, "data": [
    //             {
    //                 "highPrice24h": "120255.61",
    //                 "lowPrice24h": "116145.88",
    //                 "openPrice24h": "118919.38",
    //                 "lastPrice": "119818.83",
    //                 "turnover24h": "215859996.272276",
    //                 "volume24h": "1819.756798",
    //                 "bid1Price": "119811.26",
    //                 "ask1Price": "119831.18",
    //                 "bid1Size": "0.008732",
    //                 "ask1Size": "0.004297",
    //                 "price24hPcnt": "0.02002"
    //             }
    //         ],
    //         "ts": 1753230479687
    //     }
    //
    // unsubscribe
    //
    //     {
    //         "event": "unsubscribe",
    //         "arg": {
    //             "instType": "spot",
    //             "topic": "kline",
    //             "symbol": "BTCUSDT",
    //             "interval": "1m"
    //         }
    //     }
    //
    if (isTrue(isEqual(this->handleErrorMessage(client, message), true))) {
      return;
    }
    ccxt::any content = this->safeString(message, std::string("message"));
    if (isTrue(isEqual(content, std::string("pong")))) {
      this->handlePong(client, message);
      return;
    }
    if (isTrue(isEqual(message, std::string("pong")))) {
      this->handlePong(client, message);
      return;
    }
    ccxt::any event = this->safeString(message, std::string("event"));
    if (isTrue(isEqual(event, std::string("login")))) {
      this->handleAuthenticate(client, message);
      return;
    }
    if (isTrue(isEqual(event, std::string("subscribe")))) {
      this->handleSubscriptionStatus(client, message);
      return;
    }
    if (isTrue(isEqual(event, std::string("unsubscribe")))) {
      this->handleUnSubscriptionStatus(client, message);
      return;
    }
    ccxt::any methods = ccxt::dict{
        {std::string("ticker"), std::string("handleTicker")},
        {std::string("trade"), std::string("handleTrades")},
        {std::string("publicTrade"), std::string("handleTrades")},
        {std::string("fill"), std::string("handleMyTrades")},
        {std::string("order"), std::string("handleOrder")},
        {std::string("orders"), std::string("handleOrder")},
        {std::string("ordersAlgo"), std::string("handleOrder")},
        {std::string("orders-algo"), std::string("handleOrder")},
        {std::string("orders-crossed"), std::string("handleOrder")},
        {std::string("orders-isolated"), std::string("handleOrder")},
        {std::string("account"), std::string("handleBalance")},
        {std::string("position"), std::string("handlePositions")},
        {std::string("positions"), std::string("handlePositions")},
        {std::string("account-isolated"), std::string("handleBalance")},
        {std::string("account-crossed"), std::string("handleBalance")},
        {std::string("kline"), std::string("handleOHLCV")},
    };
    ccxt::any arg = this->safeValue(message, std::string("arg"), ccxt::dict{});
    ccxt::any topic = this->safeValue2(arg, std::string("channel"),
                                      std::string("topic"), std::string(""));
    ccxt::any method = this->safeValue(methods, topic);
    if (isTrue(!isEqual(method, ccxt::any{}))) {
      this->dispatchMethodName(method, ccxt::list{client, message});
    }
    if (isTrue(isGreaterThanOrEqual(getIndexOf(topic, std::string("candle")),
                                    0))) {
      this->handleOHLCV(client, message);
    }
    if (isTrue(
            isGreaterThanOrEqual(getIndexOf(topic, std::string("books")), 0))) {
      this->handleOrderBook(client, message);
    }
  }

